-- ds_coverage — GENERATED by tools/build_production.py from tools/dashboard_datasets.py.
-- Paste into the dashboard's Data tab as a dataset named ds_coverage.
-- One row per binding: what checks each bound column. On no stage-1 widget; kept for Genie.

SELECT cde_id, cde_name, criticality, business_domain, target_table, target_column,
       coverage_gap,
       CASE coverage_gap WHEN 'covered' THEN 'Covered'
                         WHEN 'unvalidated' THEN 'Not validated'
                         WHEN 'no_rule' THEN 'No active rule'
                         WHEN 'scope_mismatch' THEN 'Scope disputed' END        AS coverage,
       rule_count, breaching_rule_count
FROM   sdpt_data_trnf.udp_brnz.dq_results_v_cde_coverage
